CREATE OR REPLACE FUNCTION public.aqlan_hr_identity_legacy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.identity_revision < OLD.identity_revision OR NEW.identity_revision > OLD.identity_revision + 1 THEN
      RAISE EXCEPTION 'identity revision must advance one step';
    END IF;
    IF OLD.identity_revision > 0 AND (NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.user_linked_at IS DISTINCT FROM OLD.user_linked_at) THEN
      RAISE EXCEPTION 'converted identity preserves the legacy access link';
    END IF;
  END IF;
  IF NEW.user_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN
    -- The same account lock is taken by the explicit-link INSERT trigger. The
    -- check follows the lock so a concurrent writer cannot claim the other side.
    IF current_setting('transaction_isolation') <> 'read committed' THEN
      RAISE EXCEPTION 'identity account claims require read committed isolation' USING ERRCODE='40001';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('hr-person-account:' || NEW.user_id::text,0));
    IF EXISTS(SELECT 1 FROM hr_staff_account_links WHERE user_id=NEW.user_id AND staff_id<>NEW.id AND closed_at IS NULL) THEN
      RAISE EXCEPTION 'account already belongs to another converted person'
        USING ERRCODE='23505', CONSTRAINT='hr_identity_account_person_unique';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aqlan_hr_identity_link_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'hr identity links cannot be deleted'; END IF;
  IF OLD.closed_at IS NOT NULL OR NEW.closed_at IS NULL OR NEW.closed_event_id IS NULL
    OR (to_jsonb(NEW) - 'closed_at' - 'closed_event_id') IS DISTINCT FROM
       (to_jsonb(OLD) - 'closed_at' - 'closed_event_id') THEN
    RAISE EXCEPTION 'hr identity link may only be closed once with evidence';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM hr_identity_events e WHERE e.id=NEW.closed_event_id AND e.staff_id=NEW.staff_id
    AND e.action=CASE WHEN TG_TABLE_NAME='hr_staff_account_links' THEN 'close_account' ELSE 'close_party' END
    AND e.details->>'linkId'=NEW.id::text) THEN
    RAISE EXCEPTION 'link closure requires matching identity event';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aqlan_hr_identity_link_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME='hr_staff_account_links' THEN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
      RAISE EXCEPTION 'identity account claims require read committed isolation' USING ERRCODE='40001';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('hr-person-account:' || (to_jsonb(NEW)->>'user_id'),0));
  END IF;
  IF NOT EXISTS(SELECT 1 FROM hr_staff WHERE id=NEW.staff_id AND identity_revision>0) THEN
    RAISE EXCEPTION 'identity links require a converted person';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM hr_identity_events e WHERE e.id=NEW.opened_event_id AND e.staff_id=NEW.staff_id
    AND e.action=CASE WHEN TG_TABLE_NAME='hr_staff_account_links' THEN 'link_account' ELSE 'link_party' END
    AND e.details->>CASE WHEN TG_TABLE_NAME='hr_staff_account_links' THEN 'userId' ELSE 'partyId' END
      = (to_jsonb(NEW)->>CASE WHEN TG_TABLE_NAME='hr_staff_account_links' THEN 'user_id' ELSE 'party_id' END)) THEN
    RAISE EXCEPTION 'link requires matching identity event';
  END IF;
  IF TG_TABLE_NAME='hr_staff_account_links' AND EXISTS(SELECT 1 FROM hr_staff
    WHERE user_id=(to_jsonb(NEW)->>'user_id')::int AND id<>NEW.staff_id) THEN
    RAISE EXCEPTION 'account has a reserved legacy access link'
      USING ERRCODE='23505', CONSTRAINT='hr_identity_account_person_unique';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aqlan_hr_identity_party_kind()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM parties WHERE id=NEW.party_id AND kind IN ('doctor','employee')) THEN
    RAISE EXCEPTION 'hr financial identity requires doctor or employee party';
  END IF;
  RETURN NEW;
END;
$function$

